using System.ComponentModel;
using System.Text.Json;
using ModelContextProtocol.Server;

[McpServerResourceType]
public static class ConfigResource
{
    [McpServerResource(UriTemplate = "config://app/settings", Name = "App Settings",
        MimeType = "application/json")]
    [Description("Returns application configuration data including feature flags and limits.")]
    public static string GetSettings()
    {
        var config = new
        {
            Version = "1.0.0",
            Environment = "production",
            Features = new { EnableCache = true, MaxRetries = 3 },
            Endpoints = new { Api = "https://api.example.com", Docs = "https://docs.example.com" }
        };

        return JsonSerializer.Serialize(config, new JsonSerializerOptions { WriteIndented = true });
    }
}

using System.ComponentModel;
using ModelContextProtocol.Server;

[McpServerToolType]
public static class ServiceTools
{
    [McpServerTool, Description("Echoes a message back, confirming the server is operational.")]
    public static string Ping(
        [Description("Message to echo back")] string message)
    {
        return $"pong: {message}";
    }

    [McpServerTool, Description("Returns the current server time in UTC.")]
    public static string GetServerTime()
    {
        return DateTime.UtcNow.ToString("O");
    }
}

